"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[93617],{93617:function(e){e.exports=JSON.parse('{"content":"\\n<center>\\n<RestaurantCard\\n  cover=\\"/assets/snippets/location/46e1256204b7dbf196d726a9fa8392eb.jpg\\"\\n  title=\\"Bar Reggio\\"\\n  cuisine=\\"Italian\\"\\n  address=\\"135 Crown St, Darlinghurst NSW 2010 Australia\\"\\n  rating=4\\n  tags=\\"restaurant\\"\\n/>\\n</center>\\n\\n## Ordered\\n```menu\\n{\\n\\"title\\": \\"Eye Fillet with Mushroom Sauce\\",\\n\\"rating\\": 4\\n}\\n---\\nA tender eye fillet steak topped with mushroom sauce. A subtle hint of egg yolk permeates the sauce.\\n```\\n```menu\\n{\\n\\"title\\": \\"Charred Octopus Salad\\",\\n\\"rating\\": 4\\n}\\n---\\nA salad of lightly charred octopus with iceberg lettuce, tomatoes, and olives.\\n```\\n## Review\\nA place we visited on our guide\'s recommendation.  \\nWe ordered both dishes our guide recommended without hesitation.  \\n\\nWhen ordering the `Charred Octopus Salad`, they didn\'t catch it at first due to our pronunciation and accent.  \\n\\nProbably because you can bring your own wine for a small corkage fee, even on a weekday afternoon many people were enjoying wine and making plenty of noise.  \\nIt seemed like the kind of place that locals would claim as their go-to spot.  \\n```adcard\\n```\\nThe sauce on the `Eye Fillet with Mushroom Sauce` was, as expected, delicious.  \\nThere was a subtle hint of egg yolk flavor that made me want to try recreating it at home.  \\n\\nThe `Charred Octopus Salad` had the octopus cooked to just the right degree, giving it a perfect texture and flavor.  \\n\\nBoth dishes were satisfying, and it\'s a place I\'d highly recommend.  \\n## Pictures\\n<pictures>\\n<img src=\\"/assets/snippets/location/46e1256204b7dbf196d726a9fa8392eb.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Bar Reggio\\">\\n<img src=\\"/assets/snippets/location/e31a1d9480ea5067ce359bbf47ee9d87.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Bar Reggio\\">\\n<img src=\\"/assets/snippets/location/f0874bc6d7e097a12893ff9d93744b62.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Bar Reggio\\">\\n<img src=\\"/assets/snippets/location/8d386108e7ae23e198157159b425005a.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Bar Reggio\\">\\n<img src=\\"/assets/snippets/location/0595ead2935a1eb7d41443cfcf10a8dc.jpg\\" style=\\"max-width: 100%; height: auto; object-fit: contain;\\" alt=\\"Bar Reggio\\">\\n</pictures>\\n"}')}}]);